#!/usr/bin/env bash
#
# PocketPills — on-device handwriting recognition (TrOCR) for prescription OCR.
# Additive: adds src/lib/localHtr/{lineSegments,trocrWorker,htrClient}.ts and
# wires a handwriting fallback into src/lib/rxOcr.ts. Printed scans are
# unchanged (the fallback only fires when Tesseract returns near-empty text).
#
# Safe to re-run: backs up touched files, skips the rxOcr patch if already
# applied, and verifies with tsc + vite build.
#
set -euo pipefail

grep -q '"pocketpills-redesign"' package.json 2>/dev/null || {
  echo "!! Run this from the pocketpills repo root (package.json not found or wrong repo)."; exit 1; }

STAMP="$(date +%Y%m%d-%H%M%S)"
BK=".htr-backup-${STAMP}"
mkdir -p "${BK}/src/lib"
echo ">> Backups -> ${BK}/"

decode() { # decode <b64> <dest>
  mkdir -p "$(dirname "$2")"
  printf '%s' "$1" | base64 -d > "$2"
  echo "   wrote $2"
}

LINESEGMENTS_B64=""
TROCRWORKER_B64=""
HTRCLIENT_B64=""

echo ">> Writing handwriting modules"
[ -f "src/lib/localHtr/lineSegments.ts" ] && cp "src/lib/localHtr/lineSegments.ts" "${BK}/src/lib/localHtr/lineSegments.ts" 2>/dev/null || true
decode "$LINESEGMENTS_B64" "src/lib/localHtr/lineSegments.ts"
[ -f "src/lib/localHtr/trocrWorker.ts" ] && cp "src/lib/localHtr/trocrWorker.ts" "${BK}/src/lib/localHtr/trocrWorker.ts" 2>/dev/null || true
decode "$TROCRWORKER_B64" "src/lib/localHtr/trocrWorker.ts"
[ -f "src/lib/localHtr/htrClient.ts" ] && cp "src/lib/localHtr/htrClient.ts" "${BK}/src/lib/localHtr/htrClient.ts" 2>/dev/null || true
decode "$HTRCLIENT_B64" "src/lib/localHtr/htrClient.ts"

echo ">> Patching src/lib/rxOcr.ts"
cp src/lib/rxOcr.ts "${BK}/src/lib/rxOcr.ts"
if grep -q "localHtr/htrClient" src/lib/rxOcr.ts; then
  echo "   already patched — skipping"
else
  RXOCR_PATCH_B64=""
  if printf '%s' "$RXOCR_PATCH_B64" | base64 -d | git apply -p1 --check - 2>/dev/null; then
    printf '%s' "$RXOCR_PATCH_B64" | base64 -d | git apply -p1 -
    echo "   applied via git apply"
  elif printf '%s' "$RXOCR_PATCH_B64" | base64 -d | patch -p1 --dry-run >/dev/null 2>&1; then
    printf '%s' "$RXOCR_PATCH_B64" | base64 -d | patch -p1
    echo "   applied via patch"
  else
    echo "!! Could not apply rxOcr.ts patch cleanly. New files are in place;"
    echo "   apply the rxOcr.ts changes by hand (see PR notes). Backup at ${BK}."
    exit 2
  fi
fi

echo ">> Verifying (tsc)"
npx tsc -b --noEmit
echo ">> Verifying (vite build)"
npx vite build >/dev/null
echo ""
echo "✅ Done. Handwriting fallback wired in. Backup: ${BK}"
echo "   Rollback: cp -r ${BK}/src ./ && rm -rf src/lib/localHtr"

